state = {"status": "awaiting_review", "draft": "Send refund note", "approved": None}

def resume(state, decision):
    if state["status"] != "awaiting_review":
        raise ValueError("not waiting for review")
    if decision["type"] == "approve":
        return {**state, "status": "ready_to_send", "approved": True, "reviewer": decision["reviewer"]}
    if decision["type"] == "edit":
        return {**state, "status": "needs_revision", "draft": decision["draft"], "approved": False}
    if decision["type"] == "reject":
        return {**state, "status": "cancelled", "approved": False}
    return {**state, "status": "escalated", "approved": False}

print(resume(state, {"type": "edit", "draft": "Ask finance to review first", "reviewer": "pm"}))
